import{_ as t,o as a,c as r,ai as o}from"./chunks/framework.QGT6ovkH.js";const u=JSON.parse('{"title":"Researcher — External Knowledge","description":"","frontmatter":{},"headers":[],"relativePath":"agents/researcher.md","filePath":"agents/researcher.md"}'),i={name:"agents/researcher.md"};function s(n,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /opencode-team-lead/agents/researcher.md for this page in Markdown format</div><h1 id="researcher-—-external-knowledge" tabindex="-1">Researcher — External Knowledge <a class="header-anchor" href="#researcher-—-external-knowledge" aria-label="Permalink to &quot;Researcher — External Knowledge&quot;">​</a></h1><p>Researcher is the external knowledge retrieval agent. It fetches and synthesizes information from public sources — official documentation, RFCs, API references, standards bodies, reference implementations — and hands a structured report back to the calling agent.</p><p><strong>Mode:</strong> <code>subagent</code> — only reachable via <code>task</code> delegation from the team-lead.</p><h2 id="when-the-team-lead-uses-it" tabindex="-1">When the team-lead Uses It <a class="header-anchor" href="#when-the-team-lead-uses-it" aria-label="Permalink to &quot;When the team-lead Uses It&quot;">​</a></h2><p>During the <strong>comprehension phase</strong>, before planning begins, when a task requires external technical context that isn&#39;t in the codebase.</p><p>The team-lead delegates to <code>researcher</code> when:</p><ul><li>The task involves a library, framework, or protocol the codebase doesn&#39;t explain</li><li>There&#39;s an open question about best practices, standards, or API behavior</li><li>A technology choice needs evaluation against official specs</li><li>Understanding an RFC or standard is necessary before scoping the work</li></ul><p><code>researcher</code> runs before planning. Never during implementation — that&#39;s when <code>explore</code> (internal) and <code>general</code> (building) take over.</p><h2 id="the-distinction" tabindex="-1">The Distinction <a class="header-anchor" href="#the-distinction" aria-label="Permalink to &quot;The Distinction&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Agent</th></tr></thead><tbody><tr><td>Explore the internal codebase</td><td><code>explore</code></td></tr><tr><td>Retrieve external knowledge</td><td><code>researcher</code></td></tr><tr><td>Build something</td><td><code>general</code></td></tr></tbody></table><p>These are complementary, not competing. A typical mission might use all three: <code>researcher</code> for external context → <code>explore</code> for internal context → <code>general</code> for implementation.</p><h2 id="_5-phase-workflow" tabindex="-1">5-Phase Workflow <a class="header-anchor" href="#_5-phase-workflow" aria-label="Permalink to &quot;5-Phase Workflow&quot;">​</a></h2><h3 id="phase-1-—-scope" tabindex="-1">Phase 1 — Scope <a class="header-anchor" href="#phase-1-—-scope" aria-label="Permalink to &quot;Phase 1 — Scope&quot;">​</a></h3><p>Clarifies what&#39;s needed before fetching anything:</p><ul><li>What specific technical question needs answering?</li><li>What level of depth is required (overview vs. API detail vs. formal specification)?</li><li>What sources are likely authoritative?</li></ul><h3 id="phase-2-—-retrieval" tabindex="-1">Phase 2 — Retrieval <a class="header-anchor" href="#phase-2-—-retrieval" aria-label="Permalink to &quot;Phase 2 — Retrieval&quot;">​</a></h3><p>Searches 3–5 authoritative sources using websearch and webfetch. Prioritizes:</p><ul><li>Official documentation sites</li><li>RFC / specification documents</li><li>GitHub repositories (READMEs, discussions, changelogs)</li><li>npm / PyPI package documentation</li><li>MDN Web Docs</li><li>Official API references</li></ul><p>Does not rely on blog posts, StackOverflow answers, or unofficial tutorials as primary sources. Secondary sources may be used to triangulate when primary sources are ambiguous.</p><h3 id="phase-3-—-extraction" tabindex="-1">Phase 3 — Extraction <a class="header-anchor" href="#phase-3-—-extraction" aria-label="Permalink to &quot;Phase 3 — Extraction&quot;">​</a></h3><p>Pulls the relevant facts from each source. Filters out marketing copy, examples unrelated to the question, and version-specific information that doesn&#39;t apply to the project&#39;s context.</p><h3 id="phase-4-—-synthesis" tabindex="-1">Phase 4 — Synthesis <a class="header-anchor" href="#phase-4-—-synthesis" aria-label="Permalink to &quot;Phase 4 — Synthesis&quot;">​</a></h3><p>Consolidates findings across sources into a structured summary. Resolves contradictions between sources (typically by deferring to the more authoritative or more recent source). Notes explicitly what was NOT found — absence of information is information.</p><h3 id="phase-5-—-delivery" tabindex="-1">Phase 5 — Delivery <a class="header-anchor" href="#phase-5-—-delivery" aria-label="Permalink to &quot;Phase 5 — Delivery&quot;">​</a></h3><p>Returns a structured report to the team-lead with:</p><ul><li>Key findings, clearly separated by topic</li><li>Sources cited (URLs, document names, section references)</li><li>Explicit notes on gaps and unresolved questions</li><li>Confidence level for each finding (confirmed by official source vs. inferred from examples)</li></ul><h2 id="security-properties" tabindex="-1">Security Properties <a class="header-anchor" href="#security-properties" aria-label="Permalink to &quot;Security Properties&quot;">​</a></h2><p>Researcher is a read-only, leaf-node agent with specific security constraints:</p><table tabindex="0"><thead><tr><th>Property</th><th>Detail</th></tr></thead><tbody><tr><td><strong>Read-only</strong></td><td>Cannot edit or write files — retrieval only</td></tr><tr><td><strong>Leaf node</strong></td><td>Cannot delegate to other agents — no <code>task</code> tool</td></tr><tr><td><strong>SSRF-aware</strong></td><td>Will not fetch internal network URLs, private IPs, or localhost endpoints</td></tr><tr><td><strong>Prompt injection mitigation</strong></td><td>Treats all external content as untrusted data. Content from fetched pages is never interpreted as instructions.</td></tr></tbody></table><p>The SSRF constraint matters: an adversarially crafted page could embed instructions attempting to redirect the researcher to internal services or exfiltrate information. External content is data, not commands.</p><h2 id="sources-it-targets" tabindex="-1">Sources It Targets <a class="header-anchor" href="#sources-it-targets" aria-label="Permalink to &quot;Sources It Targets&quot;">​</a></h2><ul><li><strong>Language / runtime docs:</strong> MDN, docs.python.org, pkg.go.dev, nodejs.org/api, etc.</li><li><strong>Framework docs:</strong> official framework documentation sites</li><li><strong>Standards bodies:</strong> IETF RFCs, W3C specifications, NIST guidelines, OWASP</li><li><strong>Package registries:</strong> npm, PyPI, crates.io — for version, changelog, and deprecation information</li><li><strong>Reference implementations:</strong> official GitHub repositories, especially READMEs and GitHub Discussions</li><li><strong>API references:</strong> OpenAPI specs, GraphQL schemas, official API documentation</li></ul><h2 id="what-researcher-does-not-do" tabindex="-1">What Researcher Does NOT Do <a class="header-anchor" href="#what-researcher-does-not-do" aria-label="Permalink to &quot;What Researcher Does NOT Do&quot;">​</a></h2><ul><li>Access private or internal URLs — only public sources</li><li>Write files or modify the codebase</li><li>Delegate to other agents</li><li>Perform internal codebase exploration — that&#39;s <code>explore</code>&#39;s job</li><li>Implement anything — that&#39;s <code>general</code>&#39;s job</li><li>Provide implementation advice based on unofficial or unverified sources</li></ul>',35)])])}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
